import fs from 'node:fs';import { runCommand } from './src/runtime.mjs';
const args=process.argv.slice(2);const hostJsonIndex=args.indexOf('--host-json');const hostJson=hostJsonIndex>=0;if(hostJson)args.splice(hostJsonIndex,1);let candidate=null,preacceptHandoff=null,postAcceptBootstrapEvidence=null,hostEngine=process.env.IKANT_HOST_ENGINE||'motore host non dichiarato',hostSurface=process.env.IKANT_HOST_SURFACE||'LOCAL_NODE_CHAT_HOST',resourceGrants=[];for(const flag of ['--candidate-file','--preaccept-handoff-file','--bootstrap-evidence-file','--engine','--host-surface','--grant']){let idx;while((idx=args.indexOf(flag))>=0){const value=args[idx+1];if(!value){console.error(`Missing ${flag} value`);process.exit(2);}if(flag==='--candidate-file')candidate=fs.readFileSync(value,'utf8');if(flag==='--preaccept-handoff-file')preacceptHandoff=JSON.parse(fs.readFileSync(value,'utf8'));if(flag==='--bootstrap-evidence-file')postAcceptBootstrapEvidence=JSON.parse(fs.readFileSync(value,'utf8'));if(flag==='--engine')hostEngine=value;if(flag==='--host-surface')hostSurface=value;if(flag==='--grant')resourceGrants.push(...value.split(',').map(x=>x.trim()).filter(Boolean));args.splice(idx,2);}}const input=args.join(' ');try{const result=runCommand(input,{candidate,preacceptHandoff,postAcceptBootstrapEvidence,hostEngine,hostSurface,resourceGrants});if(hostJson){const envelope={schema:'ikant-le-host-result/v1',stdout:result.stdout,code:result.code,artifacts:result.artifacts||[],release:result.release||null,environment_telemetry:result.environment_telemetry||null,session_shell:result.session_shell||null};process.stdout.write(`${JSON.stringify(envelope)}
`);}else process.stdout.write(`${result.stdout}
`);process.exitCode=result.code;}catch(err){if(hostJson)process.stdout.write(`${JSON.stringify({schema:'ikant-le-host-result/v1',stdout:'',code:1,artifacts:[],release:null,environment_telemetry:null,session_shell:null,error:String(err?.message||err)})}
`);else process.stdout.write(`iKant non può completare questo passaggio in modo affidabile: ${String(err?.message||err)}
`);process.exitCode=1;}

